	private int lastXpGainTick = -100;
	private final Deque<int[]> recentXpGains = new ArrayDeque<>(); // {tick, delta}
	/** Farming XP drops still waiting to be matched to a patch change. */
	private final List<Integer> pendingActions = new ArrayList<>();
	private final List<int[]> pendingPlants = new ArrayList<>(); // {tick, itemId}
	/** Varbit ID → patches that use it (the same varbit is reused in different regions). */
	private final Map<Integer, List<PatchLocation>> patchesByVarbit = new HashMap<>();
	/** Patch changes in your region over the last few ticks. */
	private final Deque<ActionMatcher.Change> recentPatchChanges = new ArrayDeque<>();
	private final Map<Integer, Integer> lastVarbitValues = new HashMap<>();
	/** Patch objects in the loaded scene, for highlighting. */
	private final Map<PatchLocation, GameObject> patchObjects = new EnumMap<>(PatchLocation.class);
	/** Where this plugin last put the hint arrow, so it only clears its own. */
	private WorldPoint ourHintArrow;

	@Provides
	TreeRunningConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TreeRunningConfig.class);
	}

	@Override
	protected void startUp()
	{
		for (CropType crop : CropType.values())
		{
			plantedItemToCrop.put(crop.getPlantedItem().getId(), crop);
			for (int id : crop.getStockItemIds())
			{
				if (id >= 0)
				{
					trackedItems.add(id);
				}
			}
			if (crop.getPayment() != null)
			{
				trackedItems.add(crop.getPayment().getId());
			}
		}

		for (PatchLocation location : PatchLocation.values())
		{
			patchesByVarbit.computeIfAbsent(location.getVarbit(), v -> new ArrayList<>()).add(location);
		}

		debug.setEnabled(config.debugLog());
		loadBankStops();
		loadRouteOrder();
		loadTravelNotes();
		panel = new TreeRunningPanel(this);
		SwingUtilities.invokeLater(panel::loadSettings);
		navButton = NavigationButton.builder()
			.tooltip("Tree Running")
			.icon(ImageUtil.loadImageResource(TreeRunningPlugin.class, "panel_icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
		overlayManager.add(highlightOverlay);

		clientThread.invokeLater(() ->
		{
			loadState();
			lastXp = client.getGameState() == GameState.LOGGED_IN ? client.getSkillExperience(Skill.FARMING) : -1;
			refresh();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(highlightOverlay);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(this::clearOurHintArrow);
		plantedItemToCrop.clear();
		trackedItems.clear();
		pendingPlants.clear();
		pendingActions.clear();
		recentXpGains.clear();
		patchesByVarbit.clear();
		recentPatchChanges.clear();
		lastVarbitValues.clear();
		patchObjects.clear();
		inventory = new HashMap<>();
		data = PanelData.EMPTY;
		debug.shutDown();
	}

	PanelData getData()
	{
		return data;
	}

	TreeRunningConfig getConfig()
	{
		return config;
	}

	/** Patch objects in the scene; read by the highlight overlay on the client thread. */
	Map<PatchLocation, GameObject> getPatchObjects()
	{
		return patchObjects;
	}

	// ------------------------------------------------------------------ events

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadState();
		refresh();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			patchObjects.clear();
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			lastXp = client.getSkillExperience(Skill.FARMING);
			refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!TreeRunningConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		switch (event.getKey())
		{
			case "bankStops":
				loadBankStops();
				break;
			case "stopOrder":
			case "patchOrder":
				loadRouteOrder();
				break;
			case "travelText":
				loadTravelNotes();
				break;
			case "debugLog":
				debug.setEnabled(config.debugLog());
				break;
			case "hintArrow":
				if (!config.hintArrow())
				{
					clientThread.invokeLater(this::clearOurHintArrow);
				}
				break;
			default:
				break;
		}
		clientThread.invokeLater(this::refresh);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.FARMING)
		{
			return;
		}

		int xp = event.getXp();
		if (lastXp >= 0 && xp > lastXp)
		{
			int tick = client.getTickCount();
			int delta = xp - lastXp;
			lastXpGainTick = tick;
			recentXpGains.addLast(new int[]{tick, delta});
			while (!recentXpGains.isEmpty() && tick - recentXpGains.peekFirst()[0] > RUN_START_LOOKBACK_TICKS)
			{
				recentXpGains.removeFirst();
			}
			pendingActions.add(tick);
			debug.log(tick, "XP +" + delta + " (total " + xp + ") at " + where());

			if (state.active && System.currentTimeMillis() - state.lastTickAt < RUN_XP_TAIL_MS)
			{
				state.runLastXp = xp;
				saveState();
			}
		}
		lastXp = xp;
		refresh();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.INV)
		{
			Map<Integer, Integer> now = countTracked(event.getItemContainer());
			int tick = client.getTickCount();
			for (Map.Entry<Integer, Integer> entry : inventory.entrySet())
			{
				int id = entry.getKey();
				CropType crop = plantedItemToCrop.get(id);
				if (crop == null)
				{
					continue;
				}
				int gone = entry.getValue() - now.getOrDefault(id, 0);
				for (int i = 0; i < gone; i++)
				{
					pendingPlants.add(new int[]{tick, id});
				}
				if (gone > 0)
				{
					debug.log(tick, gone + "x " + crop.getPlantedItem().getName() + " left the inventory at " + where());
				}
			}
			inventory = now;
			refresh();
		}
		else if (containerId == InventoryID.BANK)
		{
			state.bank = countTracked(event.getItemContainer());
			state.bankSeenAt = System.currentTimeMillis();
			debug.log(client.getTickCount(), "Bank opened at " + where());
			tickBankStopIfNext();
			saveState();
			refresh();
		}
		else if (containerId == InventoryID.SEED_VAULT)
		{
			state.vault = countTracked(event.getItemContainer());
			state.vaultSeenAt = System.currentTimeMillis();
			saveState();
			refresh();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		List<PatchLocation> patches = patchesByVarbit.get(event.getVarbitId());
		if (patches == null)
		{
			return;
		}

		int region = currentRegion();
		int tick = client.getTickCount();
		Integer old = lastVarbitValues.put(event.getVarbitId(), event.getValue());
		List<String> here = new ArrayList<>();
		for (PatchLocation location : patches)
		{
			if (location.isInRegion(region))
			{
				recentPatchChanges.addLast(new ActionMatcher.Change(tick, location));
				here.add(location.name());
			}
		}
		while (!recentPatchChanges.isEmpty() && tick - recentPatchChanges.peekFirst().tick() > 2 * PATCH_MATCH_TICKS)
		{
			recentPatchChanges.removeFirst();
		}
		debug.log(tick, "Varbit " + event.getVarbitId() + ": " + old + " -> " + event.getValue()
			+ " in region " + region + (here.isEmpty() ? " (not a tracked patch here)" : " = " + here));
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		ObjectComposition def = client.getObjectDefinition(object.getId());
		if (def == null)
		{
			return;
		}
		List<PatchLocation> patches = patchesByVarbit.get(def.getVarbitId());
		if (patches == null || object.getWorldLocation() == null)
		{
			return;
		}
		int region = object.getWorldLocation().getRegionID();
		for (PatchLocation location : patches)
		{
			if (location.isInRegion(region))
			{
				patchObjects.put(location, object);
			}
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		patchObjects.values().removeIf(o -> o == event.getGameObject());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();
		boolean changed = false;

		// Farming XP that arrived with a patch change where you're standing: check-health,
		// planting, harvesting a Hespori. Wait until the patch change has had time to arrive.
		Iterator<Integer> actions = pendingActions.iterator();
		while (actions.hasNext())
		{
			int xpTick = actions.next();
			if (tick <= xpTick + ActionMatcher.WINDOW_TICKS)
			{
				continue;
			}
			actions.remove();
			changed |= matchAction(xpTick);
		}

		// Backup: a sapling left the inventory and Farming XP followed.
		Iterator<int[]> it = pendingPlants.iterator();
		while (it.hasNext())
		{
			int[] pending = it.next();
			if (tick > pending[0] && Math.abs(lastXpGainTick - pending[0]) <= PLANT_MATCH_TICKS)
			{
				changed |= onPlanted(plantedItemToCrop.get(pending[1]), pending[0]);
				it.remove();
			}
			else if (tick - pending[0] > PLANT_MATCH_TICKS)
			{
				// No XP followed, so it was banked, dropped or used elsewhere.
				it.remove();
			}
		}

		updateHintArrow();

		if (changed)
		{
			saveState();
			refresh();
		}
	}

	// ------------------------------------------------------------------ run tracking

	private boolean matchAction(int xpTick)
	{
		Set<PatchLocation> skip = EnumSet.noneOf(PatchLocation.class);
		for (PatchLocation location : PatchLocation.values())
		{
			if (state.done.contains(RunTask.keyFor(location, 0)) || !isPatchEnabled(location))
			{
				skip.add(location);
			}
		}
		PatchLocation location = ActionMatcher.find(xpTick, recentPatchChanges, skip);
		if (location == null)
		{
			debug.log(xpTick, "  no single patch matched this XP");
			return false;
		}

		List<RunTask> tasks = currentTasks(buildSettings());
		for (RunTask task : tasks)
		{
			if (task.getLocation() == location)
			{
				startIfNeeded(xpTick);
				markDone(task);
				lastMatch = task.getLabel();
				debug.log(xpTick, "  ticked " + task.getKey() + " (XP + patch change)");
				return true;
			}
		}
		debug.log(xpTick, "  matched " + location + " but it isn't on the run (check its crop and level)");
		return false;
	}

	private boolean onPlanted(CropType crop, int plantTick)
	{
		if (crop == null)
		{
			return false;
		}

		List<RunTask> tasks = currentTasks(buildSettings());
		Set<PatchLocation> changed = new LinkedHashSet<>();
		for (ActionMatcher.Change change : recentPatchChanges)
		{
			if (Math.abs(change.tick() - plantTick) <= PATCH_MATCH_TICKS)
			{
				changed.add(change.location());
			}
		}

		PatchMatcher.Match match = PatchMatcher.match(tasks, state.done, crop.getPatchType(), currentRegion(), changed);
		if (match == null)
		{
			debug.log(plantTick, "  planted " + crop + ": already ticked or nothing to match");
			return false;
		}
		startIfNeeded(plantTick);
		markDone(match.getTask());
		lastMatch = match.getTask().getLabel()
			+ (match.getConfidence() == PatchMatcher.Confidence.ROUTE ? " (guessed from route order)" : "");
		debug.log(plantTick, "  planted " + crop + " -> ticked " + match.getTask().getKey() + " (" + match.getConfidence() + ")");
		return true;
	}

	/** Opening your bank during a run ticks the bank stop, if a bank stop is what's next. */
	private void tickBankStopIfNext()
	{
		if (!state.active)
		{
			return;
		}
		List<RouteItem> items = Route.build(currentTasks(buildSettings()), bankStops, routeOrder);
		RouteItem next = Route.next(items, state.done);
		if (next != null && next.isBank())
		{
			state.done.add(next.getKey());
			debug.log(client.getTickCount(), "  ticked " + next.getKey());
		}
	}

	/** Ticking only marks the patch; timers and run XP are saved on Finish run. */
	private void markDone(RunTask task)
	{
		long now = System.currentTimeMillis();
		state.done.add(task.getKey());
		state.tickedAt.put(task.getKey(), now);
		state.lastTickAt = now;
		state.runLastXp = client.getSkillExperience(Skill.FARMING);
	}

	/** Starts a run if none is going, after finishing one that was left open too long. */
	private void startIfNeeded(int triggerTick)
	{
		finishIfStale();
		if (state.active)
		{
			return;
		}
		int lookback = 0;
		for (int[] gain : recentXpGains)
		{
			if (gain[0] >= triggerTick - RUN_START_LOOKBACK_TICKS)
			{
				lookback += gain[1];
			}
		}
		beginRun(client.getSkillExperience(Skill.FARMING) - lookback);
	}

	private void beginRun(int startXp)
	{
		state.active = true;
		state.startXp = startXp;
		state.startedAt = System.currentTimeMillis();
		state.lastTickAt = state.startedAt;
		state.runLastXp = 0;
		state.done.clear();
		state.tickedAt.clear();
		debug.log(client.getTickCount(), "Run started at " + startXp + " XP");
	}

	/** If you forget to press Finish run, it finishes 12 hours after its last patch (less with more runs a day). */
	private void finishIfStale()
	{
		long staleMs = (long) (Math.max(2, 12.0 / Math.max(1, config.runsPerDay())) * 3_600_000L);
		if (state.active && state.lastTickAt > 0 && System.currentTimeMillis() - state.lastTickAt >= staleMs)
		{
			debug.log(client.getTickCount(), "Run left open; finishing it");
			endRun();
		}
	}

	/** Saves the run to history and starts the growth timers of what was ticked. */
	private void endRun()
	{
		if (!state.active)
		{
			return;
		}
		List<RunTask> tasks = currentTasks(buildSettings());
		double minutesBetweenRuns = 1440.0 / Math.max(1, config.runsPerDay());
		int patches = 0;
		for (String key : state.done)
		{
			if (key.startsWith("bank:"))
			{
				continue;
			}
			patches++;
			for (RunTask task : tasks)
			{
				if (task.getKey().equals(key) && task.getCrop().getGrowthMinutes() > minutesBetweenRuns)
				{
					state.plantedAt.put(key, state.tickedAt.getOrDefault(key, System.currentTimeMillis()));
				}
			}
		}

		int endXp = state.runLastXp > 0 ? state.runLastXp : client.getSkillExperience(Skill.FARMING);
		int gained = endXp - state.startXp;
		if (gained > 0 && patches > 0)
		{
			state.runs.add(new RunRecord(System.currentTimeMillis(), gained, patches));
		}
		debug.log(client.getTickCount(), "Run finished: " + gained + " XP, " + patches + " patches");
		state.active = false;
		state.done.clear();
		state.tickedAt.clear();
		lastMatch = null;
	}

	// ------------------------------------------------------------------ hint arrow

	private void updateHintArrow()
	{
		if (!config.hintArrow())
		{
			return;
		}
		WorldPoint target = null;
		RouteItem next = data.nextItem();
		if (next != null && !next.isBank())
		{
			GameObject object = patchObjects.get(next.getTask().getLocation());
			if (object != null)
			{
				target = object.getWorldLocation();
			}
		}
		if (target == null)
		{
			clearOurHintArrow();
		}
		else if (!target.equals(ourHintArrow))
		{
			client.setHintArrow(target);
			ourHintArrow = target;
		}
	}

	private void clearOurHintArrow()
	{
		if (ourHintArrow != null && client.hasHintArrow() && ourHintArrow.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		ourHintArrow = null;
	}

	// ------------------------------------------------------------------ panel actions (called from Swing)

	void toggleTask(String key)
	{
		clientThread.invokeLater(() ->
		{
			if (state.done.remove(key))
			{
				state.tickedAt.remove(key);
				debug.log(client.getTickCount(), "Unticked " + key + " by hand");
			}
			else
			{
				startIfNeeded(client.getTickCount());
				if (key.startsWith("bank:"))
				{
					state.done.add(key);
				}
				else
				{
					for (RunTask task : currentTasks(buildSettings()))
					{
						if (task.getKey().equals(key))
						{
							markDone(task);
							break;
						}
					}
				}
				debug.log(client.getTickCount(), "Ticked " + key + " by hand");
			}
			saveState();
			refresh();
		});
	}

	void startNewRun()
	{
		clientThread.invokeLater(() ->
		{
			endRun();
			beginRun(client.getSkillExperience(Skill.FARMING));
			saveState();
			refresh();
		});
	}

	void finishRun()
	{
		clientThread.invokeLater(() ->
		{
			endRun();
			saveState();
			refresh();
		});
	}

	void deleteRun(int index)
	{
		clientThread.invokeLater(() ->
		{
			if (index >= 0 && index < state.runs.size())
			{
				state.runs.remove(index);
				saveState();
				refresh();
			}
		});
	}

	void clearHistory()
	{
		clientThread.invokeLater(() ->
		{
			state.runs.clear();
			saveState();
			refresh();
		});
	}

	// ------------------------------------------------------------------ settings (called from Swing)

	/** Saves one setting from the XP tab. ConfigManager is thread-safe. */
	void setSetting(String key, Object value)
	{
		configManager.setConfiguration(TreeRunningConfig.GROUP, key, value);
	}

	boolean isPatchEnabled(PatchLocation location)
	{
		String key = TreeRunningConfig.PATCH_KEYS.get(location);
		String value = key == null ? null : configManager.getConfiguration(TreeRunningConfig.GROUP, key);
		return value == null || Boolean.parseBoolean(value);
	}

	void setPatchEnabled(PatchLocation location, boolean enabled)
	{
		String key = TreeRunningConfig.PATCH_KEYS.get(location);
		if (key != null)
		{
			setSetting(key, enabled);
		}
	}

	/** A copy of the bank stops, for the route editor. */
	List<BankStop> getBankStops()
	{
		List<BankStop> copy = new ArrayList<>();
		for (BankStop b : bankStops)
		{
			copy.add(new BankStop(b.id, b.getRouteStep(), b.before, b.name));
		}
		return copy;
	}

	void saveBankStops(List<BankStop> stops)
	{
		bankStops = Collections.unmodifiableList(new ArrayList<>(stops));
		setSetting("bankStops", gson.toJson(stops));
	}

	static BankStop newBankStop(RouteStep step)
	{
		return new BankStop(UUID.randomUUID().toString().substring(0, 8), step, true, "");
	}

	RouteOrder getRouteOrder()
	{
		return routeOrder;
	}

	void saveRouteOrder(RouteOrder order)
	{
		routeOrder = order;
		setSetting("stopOrder", gson.toJson(order.stopNames()));
		setSetting("patchOrder", gson.toJson(order.patchNames()));
	}

	/** The travel note for a stop: the player's own, or the built-in one. */
	String travelNote(RouteStep step)
	{
		String own = travelNotes.get(step);
		return own != null ? own : step.getTravel();
	}

	Map<RouteStep, String> getTravelNotes()
	{
		return new EnumMap<>(travelNotes.isEmpty() ? new EnumMap<>(RouteStep.class) : travelNotes);
	}

	void saveTravelNotes(Map<RouteStep, String> notes)
	{
		travelNotes = Collections.unmodifiableMap(new EnumMap<>(notes.isEmpty() ? new EnumMap<>(RouteStep.class) : notes));
		Map<String, String> byName = new HashMap<>();
		for (Map.Entry<RouteStep, String> e : notes.entrySet())
		{
			byName.put(e.getKey().name(), e.getValue());
		}
		setSetting("travelText", gson.toJson(byName));
	}

	private void loadBankStops()
	{
		List<BankStop> loaded = new ArrayList<>();
		try
		{
			List<BankStop> parsed = gson.fromJson(config.bankStops(), new TypeToken<List<BankStop>>()
			{
			}.getType());
			if (parsed != null)
			{
				for (BankStop b : parsed)
				{
					if (b != null && b.id != null && b.getRouteStep() != null)
					{
						loaded.add(b);
					}
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved bank stops", e);
		}
		bankStops = Collections.unmodifiableList(loaded);
	}

	private void loadRouteOrder()
	{
		try
		{
			List<String> stops = gson.fromJson(config.stopOrder(), new TypeToken<List<String>>()
			{
			}.getType());
			Map<String, List<String>> patches = gson.fromJson(config.patchOrder(), new TypeToken<Map<String, List<String>>>()
			{
			}.getType());
			routeOrder = RouteOrder.fromNames(stops, patches);
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved route order", e);
			routeOrder = RouteOrder.defaults();
		}
	}

	private void loadTravelNotes()
	{
		Map<RouteStep, String> notes = new EnumMap<>(RouteStep.class);
		try
		{
			Map<String, String> byName = gson.fromJson(config.travelText(), new TypeToken<Map<String, String>>()
			{
			}.getType());
			if (byName != null)
			{
				for (RouteStep step : RouteStep.values())
				{
					String note = byName.get(step.name());
					if (note != null)
					{
						notes.put(step, note);
					}
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved travel notes", e);
		}
		travelNotes = Collections.unmodifiableMap(notes);
	}

	// ------------------------------------------------------------------ planning

	private PlanSettings buildSettings()
	{
		Map<PatchType, CropType> crops = new EnumMap<>(PatchType.class);
		crops.put(PatchType.TREE, config.treeCrop().crop());
		crops.put(PatchType.FRUIT_TREE, config.fruitCrop().crop());
		crops.put(PatchType.HARDWOOD, config.hardwoodCrop().crop());
		// These patch types only take one crop; each patch is switched on or off in Route & patches.
		crops.put(PatchType.CALQUAT, CropType.CALQUAT);
		crops.put(PatchType.CELASTRUS, CropType.CELASTRUS);
		crops.put(PatchType.REDWOOD, CropType.REDWOOD);
		crops.put(PatchType.HESPORI, CropType.HESPORI);

		Set<PatchLocation> enabled = EnumSet.noneOf(PatchLocation.class);
		for (PatchLocation location : PatchLocation.values())
		{
			if (isPatchEnabled(location))
			{
				enabled.add(location);
			}
		}

		return new PlanSettings(crops, enabled, goalXp(), config.runsPerDay());
	}

	/** The goal as an XP total, whichever way it was set. */
	private int goalXp()
	{
		return config.goalType() == TreeRunningConfig.GoalType.XP
			? Math.max(1, Math.min(200_000_000, config.goalXp()))
			: XpTable.xpForLevel(Math.max(2, Math.min(99, config.goalLevel())));
	}

	/** The run's patches in the player's route order. */
	private List<RunTask> currentTasks(PlanSettings settings)
	{
		return routeOrder.sort(RunPlanner.buildTasks(settings, client.getRealSkillLevel(Skill.FARMING), state.plantedAt,
			System.currentTimeMillis()));
	}

	/** Recomputes everything shown in the panel and overlays. Must run on the client thread. */
	private void refresh()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			publish(PanelData.EMPTY);
			return;
		}

		finishIfStale();

		PlanSettings settings = buildSettings();
		int xp = client.getSkillExperience(Skill.FARMING);
		int level = client.getRealSkillLevel(Skill.FARMING);
		int goalXp = settings.getGoalXp();

		List<Integer> runXp = new ArrayList<>();
		for (RunRecord r : state.runs)
		{
			runXp.add(r.xp);
		}
		XpProjection planned = XpProjection.toGoal(xp, settings);
		int counted = Math.min(config.averageOver(), runXp.size());
		double actual = XpProjection.averageOfRecent(runXp, config.averageOver());

		boolean fromActual = actual > 0;
		int runsLeft = fromActual ? XpProjection.runsAtRate(xp, goalXp, actual) : planned.getRuns();
		if (runsLeft < 0 || (!fromActual && !planned.reachesGoal()))
		{
			runsLeft = -1;
		}

		Map<CropType, Integer> plantings = runsLeft > 0
			? XpProjection.forRuns(xp, runsLeft, settings).getPlantings()
			: Collections.emptyMap();
		Map<Integer, Integer> bank = state.bank;
		Map<Integer, Integer> vault = state.vault;
		Map<Integer, Integer> inv = inventory;
		List<SupplyCalculator.SupplyLine> supplies = SupplyCalculator.compute(plantings,
			id -> bank.getOrDefault(id, 0) + vault.getOrDefault(id, 0) + inv.getOrDefault(id, 0),
			// The OSRS Wiki's live price, which RuneLite downloads and keeps up to date.
			id -> itemManager.getItemPriceWithSource(id, true));

		List<RunTask> tasks = currentTasks(settings);

		PanelData d = new PanelData();
		d.loggedIn = true;
		d.currentXp = xp;
		d.level = level;
		d.goalType = config.goalType();
		d.goalLevel = config.goalLevel();
		d.goalXp = goalXp;
		d.plannedXpPerRun = planned.getAverageXpPerRun();
		d.plannedRuns = planned.reachesGoal() ? planned.getRuns() : -1;
		d.actualXpPerRun = actual;
		d.actualRunsCounted = counted;
		d.runsLeft = runsLeft;
		d.runsLeftFromActual = fromActual;
		d.runsPerDay = settings.getRunsPerDay();
		d.tasks = tasks;
		d.items = Route.build(tasks, bankStops, routeOrder);
		d.done = new HashSet<>(state.done);
		d.runActive = state.active;
		d.runXpSoFar = state.active ? Math.max(0, xp - state.startXp) : 0;
		d.lastMatch = lastMatch;
		d.needs = RunNeeds.compute(tasks, d.done, id -> inv.getOrDefault(id, 0));
		d.supplies = supplies;
		d.bankSeenAt = state.bankSeenAt;
		d.vaultSeenAt = state.vaultSeenAt;
		d.runs = new ArrayList<>(state.runs);
		Map<RouteStep, String> travel = new EnumMap<>(RouteStep.class);
		for (RouteStep step : RouteStep.values())
		{
			travel.put(step, travelNote(step));
		}
		d.travel = travel;
		publish(d);
	}

	private void publish(PanelData snapshot)
	{
		data = snapshot;
		if (panel != null)
		{
			SwingUtilities.invokeLater(() -> panel.update(snapshot));
		}
	}

	// ------------------------------------------------------------------ helpers

	/** The map region you're standing in, translated out of instances. -1 if unknown. */
	private int currentRegion()
	{
		WorldPoint point = playerLocation();
		return point == null ? -1 : point.getRegionID();
	}

	private WorldPoint playerLocation()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}
		return client.getTopLevelWorldView().isInstance()
			? WorldPoint.fromLocalInstance(client, player.getLocalLocation())
			: player.getWorldLocation();
	}

	/** For the debug log: region and tile. */
	private String where()
	{
		WorldPoint p = playerLocation();
		return p == null ? "unknown" : "region " + p.getRegionID() + " (" + p.getX() + "," + p.getY() + "," + p.getPlane() + ")";
	}

	/** Counts tracked items, folding noted copies into their unnoted ID. */
	private Map<Integer, Integer> countTracked(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(item.getId());
			if (trackedItems.contains(id))
			{
				counts.merge(id, item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	private void loadState()
	{
		String json = configManager.getRSProfileConfiguration(TreeRunningConfig.GROUP, STATE_KEY);
		RunState loaded = null;
		if (json != null && !json.isEmpty())
		{
			try
			{
				loaded = gson.fromJson(json, RunState.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Couldn't read saved farming run state, starting fresh", e);
			}
		}
		state = loaded != null ? loaded : new RunState();
		state.fillDefaults();
	}

	private void saveState()
	{
		configManager.setRSProfileConfiguration(TreeRunningConfig.GROUP, STATE_KEY, gson.toJson(state));
	}
}

package com.treerunning.core;

import com.treerunning.data.PatchLocation;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Ties a Farming XP drop to the patch it came from: check-health, planting, harvesting a
 * Hespori, and so on. A patch counts when its varbit changed within one tick of the XP,
 * while you were standing in that patch's region. If more than one patch changed (a
 * growth tick landing at the same moment), it's too ambiguous and nothing is returned.
 */
public final class ActionMatcher
{
	/** How many ticks either side of the XP drop a patch change still counts. */
	public static final int WINDOW_TICKS = 1;

	public static final class Change
	{
		final int tick;
		final PatchLocation location;

		public Change(int tick, PatchLocation location)
		{
			this.tick = tick;
			this.location = location;
		}

		public int tick()
		{
			return tick;
		}

		public PatchLocation location()
		{
			return location;
		}
	}

	private ActionMatcher()
	{
	}

	/**
	 * @param xpTick  the tick the Farming XP arrived
	 * @param changes recent patch changes in your region
	 * @param skip    patches that shouldn't be ticked again (already done, or switched off)
	 * @return the one patch the XP came from, or null if none or several
	 */
	public static PatchLocation find(int xpTick, Collection<Change> changes, Set<PatchLocation> skip)
	{
		Set<PatchLocation> candidates = new LinkedHashSet<>();
		for (Change change : changes)
		{
			if (Math.abs(change.tick - xpTick) <= WINDOW_TICKS && !skip.contains(change.location))
			{
				candidates.add(change.location);
			}
		}
		return candidates.size() == 1 ? candidates.iterator().next() : null;
	}
}

package com.treerunning.core;

import com.treerunning.data.RouteStep;

/**
 * A bank stop the player added to their route, before or after one stop's patches.
 * Saved as JSON in the plugin settings, so fields stay simple.
 */
public final class BankStop
{
	/** Stable ID, so a stop keeps its tick if it's renamed. */
	public String id;
	/** The RouteStep this bank stop belongs to (its enum name). */
	public String step;
	/** True to bank before planting the patches at this stop, false for after. */
	public boolean before = true;
	/** Where the player banks, as they typed it. */
	public String name = "";

	public BankStop()
	{
	}

	public BankStop(String id, RouteStep step, boolean before, String name)
	{
		this.id = id;
		this.step = step.name();
		this.before = before;
		this.name = name;
	}

	/** The stop this bank belongs to, or null if the saved step no longer exists. */
	public RouteStep getRouteStep()
	{
		for (RouteStep s : RouteStep.values())
		{
			if (s.name().equals(step))
			{
				return s;
			}
		}
		return null;
	}

	/** The key used to tick it off on a run. */
	public String getKey()
	{
		return "bank:" + id;
	}

	public String getLabel()
	{
		return "Bank: " + (name == null || name.trim().isEmpty() ? "bank stop" : name.trim());
	}
}

package com.treerunning.core;

import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import java.util.Collection;
import java.util.List;
import java.util.Set;

/**
 * Decides which checklist patch you just planted.
 *
 * In order of confidence:
 * 1. A patch of the right type whose varbit changed around the moment you planted, in the
 *    region you're standing in. This tells the three Fossil Island patches apart.
 * 2. A patch of the right type in the region you're standing in.
 * 3. The next unplanted patch of that type in route order (for anywhere the plugin has no
 *    region data, or if something unexpected happens).
 */
public final class PatchMatcher
{
	public enum Confidence
	{
		/** Matched by the patch's own state change. */
		PATCH,
		/** Matched by where you're standing. */
		REGION,
		/** Guessed from route order. */
		ROUTE
	}

	public static final class Match
	{
		private final RunTask task;
		private final Confidence confidence;

		Match(RunTask task, Confidence confidence)
		{
			this.task = task;
			this.confidence = confidence;
		}

		public RunTask getTask()
		{
			return task;
		}

		public Confidence getConfidence()
		{
			return confidence;
		}
	}

	private PatchMatcher()
	{
	}

	/**
	 * @param tasks          the run's checklist, in route order
	 * @param done           task keys already planted this run
	 * @param type           the patch type of what was planted
	 * @param region         the region ID you're standing in (-1 if unknown)
	 * @param changedPatches patches whose varbit changed just before/after planting
	 * @return the matched task, or null if every patch of that type is already ticked
	 */
	public static Match match(List<RunTask> tasks, Set<String> done, PatchType type, int region,
		Collection<PatchLocation> changedPatches)
	{
		for (RunTask task : tasks)
		{
			if (open(task, done, type) && changedPatches.contains(task.getLocation()) && task.getLocation().isInRegion(region))
			{
				return new Match(task, Confidence.PATCH);
			}
		}

		for (RunTask task : tasks)
		{
			if (open(task, done, type) && task.getLocation().isInRegion(region))
			{
				return new Match(task, Confidence.REGION);
			}
		}

		// You're at a stop that has this kind of patch, but it's already ticked (usually by
		// its check-health a moment ago). Don't guess another stop.
		for (RunTask task : tasks)
		{
			if (task.getLocation().getPatchType() == type && task.getLocation().isInRegion(region))
			{
				return null;
			}
		}

		// Planted somewhere the plugin can't place. Fall back to route order, but only
		// among due patches.
		for (RunTask task : tasks)
		{
			if (open(task, done, type) && task.isDue())
			{
				return new Match(task, Confidence.ROUTE);
			}
		}
		return null;
	}

	/** Not ticked yet and the right type. Not-due patches count too: you can only plant where it's ready. */
	private static boolean open(RunTask task, Set<String> done, PatchType type)
	{
		return !done.contains(task.getKey()) && task.getLocation().getPatchType() == type;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import com.treerunning.data.PatchType;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/**
 * What the player has chosen: which crop goes in each patch type, which patches they use,
 * their goal (always stored as an XP total) and how many runs they do a day.
 */
public final class PlanSettings
{
	private final Map<PatchType, CropType> crops;
	private final Set<PatchLocation> enabled;
	private final int goalXp;
	private final int runsPerDay;

	public PlanSettings(Map<PatchType, CropType> crops, Set<PatchLocation> enabled, int goalXp, int runsPerDay)
	{
		this.crops = Collections.unmodifiableMap(new EnumMap<>(crops));
		this.enabled = enabled.isEmpty()
			? Collections.unmodifiableSet(EnumSet.noneOf(PatchLocation.class))
			: Collections.unmodifiableSet(EnumSet.copyOf(enabled));
		this.goalXp = Math.max(1, goalXp);
		this.runsPerDay = Math.max(1, runsPerDay);
	}

	/** The crop for a patch type, or null if that patch type is switched off. */
	public CropType cropFor(PatchType type)
	{
		return crops.get(type);
	}

	public boolean isEnabled(PatchLocation location)
	{
		return enabled.contains(location) && crops.get(location.getPatchType()) != null;
	}

	public int getGoalXp()
	{
		return goalXp;
	}

	public int getRunsPerDay()
	{
		return runsPerDay;
	}
}

package com.treerunning.core;

import com.treerunning.data.RouteStep;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 * Puts patches and bank stops in the order you do them: stops in the player's order, and at
 * each stop the bank stops set to "before", then its patches, then the bank stops set to "after".
 */
public final class Route
{
	private Route()
	{
	}

	public static List<RouteItem> build(List<RunTask> tasks, List<BankStop> bankStops)
	{
		return build(tasks, bankStops, RouteOrder.defaults());
	}

	/** Tasks should already be sorted with {@link RouteOrder#sort}. */
	public static List<RouteItem> build(List<RunTask> tasks, List<BankStop> bankStops, RouteOrder order)
	{
		List<RouteItem> items = new ArrayList<>();
		for (RouteStep step : order.getStops())
		{
			addBanks(items, step, bankStops, true);
			for (RunTask task : tasks)
			{
				if (task.getStep() == step)
				{
					items.add(RouteItem.patch(task));
				}
			}
			addBanks(items, step, bankStops, false);
		}
		return items;
	}

	private static void addBanks(List<RouteItem> items, RouteStep step, List<BankStop> bankStops, boolean before)
	{
		for (BankStop bank : bankStops)
		{
			if (bank.getRouteStep() == step && bank.before == before)
			{
				items.add(RouteItem.bank(step, bank));
			}
		}
	}

	/**
	 * The next thing to do: the first unplanted due patch, or a bank stop that still has
	 * unplanted due patches after it. Null when the run is finished.
	 */
	public static RouteItem next(List<RouteItem> items, Set<String> done)
	{
		for (int i = 0; i < items.size(); i++)
		{
			RouteItem item = items.get(i);
			if (done.contains(item.getKey()))
			{
				continue;
			}
			if (!item.isBank())
			{
				if (item.getTask().isDue())
				{
					return item;
				}
			}
			else if (hasPatchAfter(items, i, done))
			{
				return item;
			}
		}
		return null;
	}

	private static boolean hasPatchAfter(List<RouteItem> items, int index, Set<String> done)
	{
		for (int j = index + 1; j < items.size(); j++)
		{
			RouteItem later = items.get(j);
			if (!later.isBank() && later.getTask().isDue() && !done.contains(later.getKey()))
			{
				return true;
			}
		}
		return false;
	}

	/** The first stop after this one that still has something to do. */
	public static RouteStep stepAfter(List<RouteItem> items, RouteItem current, Set<String> done)
	{
		boolean passed = false;
		for (RouteItem item : items)
		{
			if (item == current)
			{
				passed = true;
				continue;
			}
			if (passed && item.getStep() != current.getStep() && item.isDue() && !done.contains(item.getKey()))
			{
				return item.getStep();
			}
		}
		return null;
	}
}

package com.treerunning.core;

import com.treerunning.data.RouteStep;

/**
 * One line of the run, in order: a patch to plant or a bank stop.
 */
public final class RouteItem
{
	private final RouteStep step;
	private final RunTask task;
	private final BankStop bank;

	private RouteItem(RouteStep step, RunTask task, BankStop bank)
	{
		this.step = step;
		this.task = task;
		this.bank = bank;
	}

	static RouteItem patch(RunTask task)
	{
		return new RouteItem(task.getStep(), task, null);
	}

	static RouteItem bank(RouteStep step, BankStop bank)
	{
		return new RouteItem(step, null, bank);
	}

	public RouteStep getStep()
	{
		return step;
	}

	public boolean isBank()
	{
		return bank != null;
	}

	/** The patch, or null for a bank stop. */
	public RunTask getTask()
	{
		return task;
	}

	/** The bank stop, or null for a patch. */
	public BankStop getBank()
	{
		return bank;
	}

	public String getKey()
	{
		return isBank() ? bank.getKey() : task.getKey();
	}

	/** Patches that aren't ready yet can't be done; bank stops always can. */
	public boolean isDue()
	{
		return isBank() || task.isDue();
	}
}

package com.treerunning.core;

import com.treerunning.data.PatchLocation;
import com.treerunning.data.RouteStep;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The order you visit the stops in, and the order of the patches at each stop. Anything the
 * player hasn't moved keeps its built-in order. Saved as two JSON settings.
 */
public final class RouteOrder
{
	private final List<RouteStep> stops;
	private final Map<RouteStep, List<PatchLocation>> patches;

	private RouteOrder(List<RouteStep> stops, Map<RouteStep, List<PatchLocation>> patches)
	{
		this.stops = stops;
		this.patches = patches;
	}

	/** The built-in order. */
	public static RouteOrder defaults()
	{
		return of(Collections.emptyList(), Collections.emptyMap());
	}

	/**
	 * Builds an order from saved names. Unknown names are ignored and anything missing is
	 * added in its built-in position, so new stops and patches always appear.
	 */
	public static RouteOrder fromNames(List<String> stopNames, Map<String, List<String>> patchNames)
	{
		List<RouteStep> stops = new ArrayList<>();
		if (stopNames != null)
		{
			for (String name : stopNames)
			{
				RouteStep step = step(name);
				if (step != null && !stops.contains(step))
				{
					stops.add(step);
				}
			}
		}
		Map<RouteStep, List<PatchLocation>> patches = new EnumMap<>(RouteStep.class);
		if (patchNames != null)
		{
			for (Map.Entry<String, List<String>> e : patchNames.entrySet())
			{
				RouteStep step = step(e.getKey());
				if (step == null || e.getValue() == null)
				{
					continue;
				}
				List<PatchLocation> list = new ArrayList<>();
				for (String name : e.getValue())
				{
					PatchLocation location = location(name);
					if (location != null && location.getStep() == step && !list.contains(location))
					{
						list.add(location);
					}
				}
				patches.put(step, list);
			}
		}
		return of(stops, patches);
	}

	private static RouteOrder of(List<RouteStep> savedStops, Map<RouteStep, List<PatchLocation>> savedPatches)
	{
		List<RouteStep> stops = new ArrayList<>(savedStops);
		for (RouteStep step : RouteStep.values())
		{
			if (!stops.contains(step))
			{
				// Put new stops after the stop that comes before them in the built-in order.
				int at = stops.size();
				for (int i = step.ordinal() - 1; i >= 0; i--)
				{
					int idx = stops.indexOf(RouteStep.values()[i]);
					if (idx >= 0)
					{
						at = idx + 1;
						break;
					}
				}
				if (step.ordinal() == 0)
				{
					at = 0;
				}
				stops.add(at, step);
			}
		}
		Map<RouteStep, List<PatchLocation>> patches = new EnumMap<>(RouteStep.class);
		for (RouteStep step : RouteStep.values())
		{
			List<PatchLocation> list = new ArrayList<>(savedPatches.getOrDefault(step, Collections.emptyList()));
			for (PatchLocation location : PatchLocation.values())
			{
				if (location.getStep() == step && !list.contains(location))
				{
					list.add(location);
				}
			}
			patches.put(step, Collections.unmodifiableList(list));
		}
		return new RouteOrder(Collections.unmodifiableList(stops), Collections.unmodifiableMap(patches));
	}

	public List<RouteStep> getStops()
	{
		return stops;
	}

	public List<PatchLocation> getPatches(RouteStep step)
	{
		return patches.get(step);
	}

	public List<String> stopNames()
	{
		List<String> names = new ArrayList<>();
		for (RouteStep step : stops)
		{
			names.add(step.name());
		}
		return names;
	}

	public Map<String, List<String>> patchNames()
	{
		Map<String, List<String>> names = new HashMap<>();
		for (Map.Entry<RouteStep, List<PatchLocation>> e : patches.entrySet())
		{
			List<String> list = new ArrayList<>();
			for (PatchLocation location : e.getValue())
			{
				list.add(location.name());
			}
			names.put(e.getKey().name(), list);
		}
		return names;
	}

	/** Moves a stop earlier (-1) or later (+1) in the route. */
	public RouteOrder moveStop(RouteStep step, int direction)
	{
		List<RouteStep> list = new ArrayList<>(stops);
		int i = list.indexOf(step);
		int j = i + direction;
		if (i >= 0 && j >= 0 && j < list.size())
		{
			Collections.swap(list, i, j);
		}
		return of(list, patches);
	}

	/** Moves a patch up (-1) or down (+1) within its stop. */
	public RouteOrder movePatch(PatchLocation location, int direction)
	{
		Map<RouteStep, List<PatchLocation>> copy = new EnumMap<>(RouteStep.class);
		copy.putAll(patches);
		List<PatchLocation> list = new ArrayList<>(patches.get(location.getStep()));
		int i = list.indexOf(location);
		int j = i + direction;
		if (i >= 0 && j >= 0 && j < list.size())
		{
			Collections.swap(list, i, j);
		}
		copy.put(location.getStep(), list);
		return of(stops, copy);
	}

	/** Sorts tasks by stop, then by patch, in this order. */
	public List<RunTask> sort(List<RunTask> tasks)
	{
		List<RunTask> sorted = new ArrayList<>(tasks);
		sorted.sort(Comparator
			.comparingInt((RunTask t) -> stops.indexOf(t.getStep()))
			.thenComparingInt(t -> patches.get(t.getStep()).indexOf(t.getLocation()))
			.thenComparingInt(RunTask::getIndex));
		return Collections.unmodifiableList(sorted);
	}

	private static RouteStep step(String name)
	{
		for (RouteStep s : RouteStep.values())
		{
			if (s.name().equals(name))
			{
				return s;
			}
		}
		return null;
	}

	private static PatchLocation location(String name)
	{
		for (PatchLocation l : PatchLocation.values())
		{
			if (l.name().equals(name))
			{
				return l;
			}
		}
		return null;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;

/**
 * Saplings and protection payments the rest of this run needs, one line per crop in route
 * order, against what's in your inventory.
 */
public final class RunNeeds
{
	public static final class Line
	{
		private final CropType crop;
		private final int saplings;
		private final int saplingsCarried;
		private final int payment;
		private final int paymentCarried;

		Line(CropType crop, int saplings, int saplingsCarried, int payment, int paymentCarried)
		{
			this.crop = crop;
			this.saplings = saplings;
			this.saplingsCarried = saplingsCarried;
			this.payment = payment;
			this.paymentCarried = paymentCarried;
		}

		public CropType getCrop()
		{
			return crop;
		}

		/** Saplings (or Hespori seeds) still to plant. */
		public int getSaplings()
		{
			return saplings;
		}

		/** How many of those are in your inventory. */
		public int getSaplingsCarried()
		{
			return saplingsCarried;
		}

		/** Protection items still needed, 0 when the crop can't be protected (Hespori). */
		public int getPayment()
		{
			return payment;
		}

		/** How many of those are in your inventory (noted counts). */
		public int getPaymentCarried()
		{
			return paymentCarried;
		}

		public boolean isShort()
		{
			return saplingsCarried < saplings || paymentCarried < payment;
		}
	}

	private RunNeeds()
	{
	}

	/** Totals for the whole run, ignoring your inventory. */
	public static List<Line> compute(List<RunTask> tasks)
	{
		return compute(tasks, java.util.Collections.emptySet(), id -> Integer.MAX_VALUE / 4);
	}

	/**
	 * @param tasks     the run's patches, in route order
	 * @param done      patches already ticked (they don't need anything any more)
	 * @param inventory how many of an unnoted item ID you're carrying (noted copies included)
	 */
	public static List<Line> compute(List<RunTask> tasks, Set<String> done, IntUnaryOperator inventory)
	{
		Map<CropType, Integer> counts = new LinkedHashMap<>();
		for (RunTask task : tasks)
		{
			if (task.isDue() && !done.contains(task.getKey()))
			{
				counts.merge(task.getCrop(), 1, Integer::sum);
			}
		}

		// Several crops can share a payment item (coconuts for magic and dragonfruit), so
		// what you carry is handed out in route order.
		Map<Integer, Integer> pool = new HashMap<>();
		List<Line> lines = new ArrayList<>();
		for (Map.Entry<CropType, Integer> e : counts.entrySet())
		{
			CropType crop = e.getKey();
			int saplings = e.getValue();
			int saplingId = crop.getPlantedItem().getId();
			int saplingsCarried = take(pool, saplingId, saplings, inventory);

			int payment = 0;
			int paymentCarried = 0;
			if (crop.getPayment() != null)
			{
				payment = saplings * crop.getPaymentQuantity();
				paymentCarried = take(pool, crop.getPayment().getId(), payment, inventory);
			}
			lines.add(new Line(crop, saplings, saplingsCarried, payment, paymentCarried));
		}
		return lines;
	}

	private static int take(Map<Integer, Integer> pool, int id, int wanted, IntUnaryOperator inventory)
	{
		int left = pool.computeIfAbsent(id, inventory::applyAsInt);
		int got = Math.min(left, wanted);
		pool.put(id, left - got);
		return got;
	}

	public static int totalSaplings(List<Line> lines)
	{
		int total = 0;
		for (Line line : lines)
		{
			total += line.getSaplings();
		}
		return total;
	}

	public static int shortCount(List<Line> lines)
	{
		int n = 0;
		for (Line line : lines)
		{
			if (line.isShort())
			{
				n++;
			}
		}
		return n;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * Builds the checklist for a run: every enabled patch in route order, with patches that
 * are still growing (or need a higher level) marked as not due.
 */
public final class RunPlanner
{
	private RunPlanner()
	{
	}

	/**
	 * @param plantedAt when each long-growing patch was last planted (task key → epoch millis)
	 */
	public static List<RunTask> buildTasks(PlanSettings settings, int farmingLevel, Map<String, Long> plantedAt, long nowMillis)
	{
		List<PatchLocation> locations = new ArrayList<>(Arrays.asList(PatchLocation.values()));
		locations.sort(Comparator
			.comparingInt((PatchLocation l) -> l.getStep().ordinal())
			.thenComparingInt(Enum::ordinal));

		double minutesBetweenRuns = 1440.0 / settings.getRunsPerDay();
		List<RunTask> tasks = new ArrayList<>();
		for (PatchLocation location : locations)
		{
			if (!settings.isEnabled(location))
			{
				continue;
			}

			CropType crop = settings.cropFor(location.getPatchType());
			for (int i = 0; i < location.getPatchCount(); i++)
			{
				String key = RunTask.keyFor(location, i);
				boolean due = true;
				String note = null;

				if (crop.getLevel() > farmingLevel)
				{
					due = false;
					note = "Needs " + crop.getLevel() + " Farming";
				}
				else if (crop.getGrowthMinutes() > minutesBetweenRuns)
				{
					Long planted = plantedAt.get(key);
					if (planted != null)
					{
						long readyAt = planted + crop.getGrowthMinutes() * 60_000L;
						if (nowMillis < readyAt)
						{
							due = false;
							note = "Ready in " + formatDuration(readyAt - nowMillis);
						}
					}
				}

				tasks.add(new RunTask(location, i, crop, due, note));
			}
		}
		return tasks;
	}

	static String formatDuration(long millis)
	{
		long totalMinutes = Math.max(0, millis) / 60_000L;
		long hours = totalMinutes / 60;
		long minutes = totalMinutes % 60;
		if (hours >= 24)
		{
			return (hours / 24) + "d " + (hours % 24) + "h";
		}
		return hours + "h " + minutes + "m";
	}
}

