package com.treerunning.core;

import com.treerunning.data.CropType;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntToLongFunction;
import java.util.function.IntUnaryOperator;

/**
 * Compares what the remaining runs need against what you have (bank, seed vault and
 * inventory), with the Grand Exchange price of each item.
 */
public final class SupplyCalculator
{
	private SupplyCalculator()
	{
	}

	public static final class SupplyLine
	{
		private final String name;
		private final boolean payment;
		private final int need;
		private final int have;
		private final long priceEach;

		SupplyLine(String name, boolean payment, int need, int have, long priceEach)
		{
			this.name = name;
			this.payment = payment;
			this.need = need;
			this.have = have;
			this.priceEach = priceEach;
		}

		/** For crops: the crop name (seeds + seedlings + saplings). For payments: the item name. */
		public String getName()
		{
			return name;
		}

		public boolean isPayment()
		{
			return payment;
		}

		public int getNeed()
		{
			return need;
		}

		public int getHave()
		{
			return have;
		}

		public int getShort()
		{
			return Math.max(0, need - have);
		}

		/** GE price of one (the seed, for crops). 0 when it can't be traded or has no price. */
		public long getPriceEach()
		{
			return priceEach;
		}

		/** What it would cost to buy what you're short of. */
		public long getShortCost()
		{
			return getShort() * priceEach;
		}
	}

	/**
	 * @param plantings how many of each crop the remaining runs plant
	 * @param haveById  how many of an unnoted item ID you own (noted copies included)
	 * @param priceById GE price of one of an item ID (0 if unknown)
	 */
	public static List<SupplyLine> compute(Map<CropType, Integer> plantings, IntUnaryOperator haveById, IntToLongFunction priceById)
	{
		List<SupplyLine> crops = new ArrayList<>();
		Map<Integer, String> paymentNames = new LinkedHashMap<>();
		Map<Integer, Integer> paymentNeed = new LinkedHashMap<>();

		for (Map.Entry<CropType, Integer> entry : plantings.entrySet())
		{
			CropType crop = entry.getKey();
			int count = entry.getValue();
			if (count <= 0)
			{
				continue;
			}

			int have = 0;
			for (int id : crop.getStockItemIds())
			{
				if (id >= 0)
				{
					have += haveById.applyAsInt(id);
				}
			}
			// Crop rows count seeds, seedlings and saplings together.
			String label = crop.getSapling() != null ? crop.getDisplayName() : crop.getSeed().getName();
			crops.add(new SupplyLine(label, false, count, have, Math.max(0, priceById.applyAsLong(crop.getSeed().getId()))));

			if (crop.getPayment() != null)
			{
				int id = crop.getPayment().getId();
				paymentNames.putIfAbsent(id, crop.getPayment().getName());
				paymentNeed.merge(id, count * crop.getPaymentQuantity(), Integer::sum);
			}
		}

		List<SupplyLine> lines = new ArrayList<>(crops);
		for (Map.Entry<Integer, Integer> entry : paymentNeed.entrySet())
		{
			int id = entry.getKey();
			lines.add(new SupplyLine(paymentNames.get(id), true, entry.getValue(), haveById.applyAsInt(id),
				Math.max(0, priceById.applyAsLong(id))));
		}
		return lines;
	}

	/** Total cost of everything you're short of. */
	public static long shortCost(List<SupplyLine> lines)
	{
		long total = 0;
		for (SupplyLine line : lines)
		{
			total += line.getShortCost();
		}
		return total;
	}
}

package com.treerunning.core;

import com.treerunning.data.CropType;
import com.treerunning.data.PatchLocation;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Simulates future runs to estimate how many runs reach the goal and how many of each
 * crop get planted along the way.
 *
 * Each run plants every enabled patch whose crop is unlocked at the current level. Crops
 * that take longer than the time between runs (hardwood, redwood, Hespori) are replanted
 * every N runs. XP is credited on the run it's planted, which matches the daily rhythm of
 * checking yesterday's tree and planting today's.
 */
public final class XpProjection
{
	/** Safety cap so a misconfigured plan can't loop forever. */
	public static final int MAX_RUNS = 5000;

	private final int runs;
	private final boolean reachesGoal;
	private final double averageXpPerRun;
	private final Map<CropType, Integer> plantings;

	private XpProjection(int runs, boolean reachesGoal, double averageXpPerRun, Map<CropType, Integer> plantings)
	{
		this.runs = runs;
		this.reachesGoal = reachesGoal;
		this.averageXpPerRun = averageXpPerRun;
		this.plantings = Collections.unmodifiableMap(plantings);
	}

	/** Runs needed to go from currentXp to the plan's goal using planned crop XP. */
	public static XpProjection toGoal(int currentXp, PlanSettings settings)
	{
		return simulate(currentXp, settings.getGoalXp(), settings, MAX_RUNS);
	}

	/** What a fixed number of runs plants (used when runs come from real run history). */
	public static XpProjection forRuns(int currentXp, int runs, PlanSettings settings)
	{
		return simulate(currentXp, Integer.MAX_VALUE, settings, runs);
	}

	private static XpProjection simulate(int currentXp, int goalXp, PlanSettings settings, int maxRuns)
	{
		Map<CropType, Integer> plantings = new EnumMap<>(CropType.class);
		Map<PatchLocation, Integer> lastPlantedRun = new HashMap<>();
		double xp = currentXp;
		int run = 0;

		while (xp < goalXp && run < maxRuns)
		{
			run++;
			int level = XpTable.levelForXp((int) xp);
			double gained = 0;

			for (PatchLocation location : PatchLocation.values())
			{
				if (!settings.isEnabled(location))
				{
					continue;
				}
				CropType crop = settings.cropFor(location.getPatchType());
				if (crop.getLevel() > level)
				{
					continue;
				}
				Integer last = lastPlantedRun.get(location);
				if (last != null && run - last < crop.getIntervalRuns(settings.getRunsPerDay()))
				{
					continue;
				}
				gained += crop.getXp() * location.getPatchCount();
				plantings.merge(crop, location.getPatchCount(), Integer::sum);
				lastPlantedRun.put(location, run);
			}

			if (gained <= 0)
			{
				// Nothing can be planted at this level, so the goal is unreachable.
				break;
			}
			xp += gained;
		}

		boolean reached = xp >= goalXp;
		double average = run == 0 ? 0 : (Math.min(xp, goalXp) - currentXp) / run;
		return new XpProjection(run, reached, average, plantings);
	}

	public int getRuns()
	{
		return runs;
	}

	public boolean reachesGoal()
	{
		return reachesGoal;
	}

	public double getAverageXpPerRun()
	{
		return averageXpPerRun;
	}

	public Map<CropType, Integer> getPlantings()
	{
		return plantings;
	}

	/** Average XP of the most recent completed runs (0 if there are none). */
	public static double averageOfRecent(List<Integer> runXp, int count)
	{
		if (runXp.isEmpty() || count <= 0)
		{
			return 0;
		}
		int from = Math.max(0, runXp.size() - count);
		long sum = 0;
		int n = 0;
		for (int i = from; i < runXp.size(); i++)
		{
			sum += runXp.get(i);
			n++;
		}
		return n == 0 ? 0 : (double) sum / n;
	}

	/** Runs needed at a given XP per run (0 if the goal is already reached). */
	public static int runsAtRate(int currentXp, int goalXp, double xpPerRun)
	{
		if (currentXp >= goalXp)
		{
			return 0;
		}
		if (xpPerRun <= 0)
		{
			return -1;
		}
		return (int) Math.ceil((goalXp - currentXp) / xpPerRun);
	}
}

package com.treerunning.core;

/**
 * The standard OSRS experience table.
 */
public final class XpTable
{
	private static final int[] XP_FOR_LEVEL = new int[127];

	static
	{
		double points = 0;
		for (int level = 1; level < XP_FOR_LEVEL.length; level++)
		{
			XP_FOR_LEVEL[level] = (int) Math.floor(points / 4);
			points += Math.floor(level + 300 * Math.pow(2, level / 7.0));
		}
	}

	private XpTable()
	{
	}

	/** Total XP needed to reach a level (1–126). */
	public static int xpForLevel(int level)
	{
		int clamped = Math.max(1, Math.min(126, level));
		return XP_FOR_LEVEL[clamped];
	}

	/** The level a given amount of XP is worth (capped at 99). */
	public static int levelForXp(int xp)
	{
		int level = 1;
		while (level < 99 && xp >= XP_FOR_LEVEL[level + 1])
		{
			level++;
		}
		return level;
	}
}

